head.script:
scwin.imgClick = function(row, colID, data) {
    //alert("row : " + row + ", colID : " + colID + ", data : " + data);
}
scwin.fireOver = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.mouseOverBehaviour = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireOver(el);
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 inputType 이 textImage 인 컬럼을 마우스 오버한다.
    //1. In your browser, mouse over the column whose inputType is textImage.
    //Verify step 1. The tooltip of the mouse over column is displayed.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour($p.id+'grid1_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_tooltip').text() == 'a1'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    grid1.setXML(WebSquare.ModelUtil.findInstanceNode("vector"));
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 28-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
